      key: prevKey, accountId, leagueId: _leagueTermOf(prevKey),
      draftPicks: captured.draftPicks,
      draftTiebreaker: captured.draftTiebreaker,
      draftExtraPoint: captured.draftExtraPoint,
      layoutEditing: captured.layoutEditing,
